message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure or blockage observed in an earlier execution step, for example by installing a compatible version, switching tooling, or altering an approach.",
      "source_description": "An earlier observed execution failure or resource blockage (e.g., a missing module or an unsatisfiable version requirement).",
      "target_description": "A subsequent agent action intended to resolve that failure or bypass the blockage."
    },
    {
      "name": "DIAGNOSES_CAUSE_OF_FAILURE",
      "definition": "The agent performs an information-gathering action to determine the underlying cause of an earlier failure before or while attempting to fix it.",
      "source_description": "An earlier observed execution failure whose cause is not yet understood.",
      "target_description": "A subsequent diagnostic action that inspects environment or configuration state to explain the failure."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent action consumes data, values, or intermediate results obtained from an earlier execution step as its input or starting point for further processing.",
      "source_description": "An earlier execution result or observation that produces usable data or values.",
      "target_description": "A subsequent action that consumes that earlier result as input."
    },
    {
      "name": "EVALUATES_ALTERNATIVES_TO_SELECT_BEST",
      "definition": "The agent compares multiple candidate hypotheses, models, or configurations using a quantitative criterion and adopts the best-scoring one for subsequent processing.",
      "source_description": "A set of candidate alternatives that are scored or compared against each other.",
      "target_description": "The selected alternative that is carried forward into subsequent actions."
    },
    {
      "name": "VERIFIES_PRODUCED_OUTPUT",
      "definition": "A subsequent agent action inspects or checks an artifact produced by an earlier action in order to confirm that it was created correctly and meets the expected format or content.",
      "source_description": "An earlier action that produced an output artifact or result.",
      "target_description": "A subsequent verification action that inspects the produced artifact."
    }
  ]
}

